using System;using System.IO;using System.Linq;using System.Collections.Generic;using Mewgic;using Mewgic.Core;using Mewgic.Rewards;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using Unity.Profiling;
[InitializeOnLoad]public static class BetaPlayTests
{
 static string output;static Queue<Action> actions=new Queue<Action>();static List<string> checks=new List<string>();static double next;static string original;static bool had;static int transitions,expectedTransitions;static float volume;static ProfilerRecorder gc;static bool sampling;static List<long> samples=new List<long>();static List<object> performance=new List<object>();static double deadline;static bool ready;static int goStart;static long memoryStart;
 static BetaPlayTests(){EditorApplication.update+=Tick;}
 static void Check(bool v,string m){if(!v)throw new Exception(m);checks.Add(m);}
 static void Add(Action a)=>actions.Enqueue(a);static void Tap(string name)=>Add(()=>Click(name));
 static void Click(string name){Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"Exists "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Top raycast "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
 static void Capture(string name)=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART08_"+name+"_GAMEVIEW.png");
 static void SceneLoaded(Scene scene,LoadSceneMode mode){transitions++;}
 static void BeginSample(){samples.Clear();goStart=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;memoryStart=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong();sampling=true;}
 static void EndSample(string screen){sampling=false;var ordered=samples.OrderBy(x=>x).ToArray();int objects=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;performance.Add(new{screen,samples=ordered.Length,recorderValid=gc.Valid,gcMedianBytes=ordered.Length==0?0:ordered[ordered.Length/2],gcP95Bytes=ordered.Length==0?0:ordered[(int)((ordered.Length-1)*.95)],objectsStart=goStart,objectsEnd=objects,memoryStart,memoryEnd=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),particleSystems=UnityEngine.Object.FindObjectsByType<ParticleSystem>(FindObjectsSortMode.None).Length});Check(objects<=goStart+1,"Steady-state GameObject pool bounded "+screen);}
 public static void Run()
 {
  if(EditorApplication.isPlaying)throw new Exception("Stop Play first");output=BetaCapturePaths.NewRun("BetaPlay");actions.Clear();checks.Clear();performance.Clear();had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);original=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");volume=AudioListener.volume;transitions=0;ready=false;deadline=EditorApplication.timeSinceStartup+90;SceneManager.sceneLoaded+=SceneLoaded;
  GameplayProgress.UseTestProfile();GameplayLevelCatalog.ResetSelection();gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame",1);
  Add(()=>{Check(SceneManager.GetActiveScene().name=="Home","Boot resolves Home");Check(!UnityEngine.Object.FindFirstObjectByType<HomeTopBar>().Model.IsPreview&&UnityEngine.Object.FindFirstObjectByType<HomeTopBar>().Model.Coins==0,"Player presentation selected");Capture("HOME");BeginSample();});
  for(int i=0;i<5;i++)Add(()=>{});Add(()=>EndSample("Home"));
  foreach(string n in new[]{"CoinsPlus","GemsPlus","EnergyPlus","NavTeam","NavInventory"}){Tap(n);Add(()=>Check(GameObject.Find("ResourceInfoPanel")!=null,"Explicit unavailable system panel"));Tap("ResourceInfoClose");}
  Tap("SettingsButton");Add(()=>{Check(GameObject.Find("SoundToggle")!=null,"Real minimal settings control");Capture("SETTINGS");SettingsLayout(900,1600,false);SettingsLayout(900,1950,false);SettingsLayout(900,2000,true);SettingsLayout(360,640,true);});Tap("SoundToggle");Add(()=>Check(!GameplayProgress.Current.Presentation.soundEnabled&&AudioListener.volume==0,"Sound off saved and applied"));Tap("ResourceInfoClose");Tap("SettingsButton");Add(()=>Check(GameObject.Find("SoundToggle/Label").GetComponent<TMPro.TMP_Text>().text.Contains("KAPALI"),"Settings reopen retains preference"));Tap("SoundToggle");Tap("ResourceInfoClose");
  Add(()=>{var p=GameplayProgress.Current;p.Claim(1,3,true,out _);p.SetCurrentLevel(2);GameplayLevelCatalog.ResetSelection();GameplayLevelCatalog.ResumeFromSave();Check(GameplayLevelCatalog.SelectedId==2,"Persisted verified unlocked selection restored");p.SetCurrentLevel(999);GameplayLevelCatalog.ResumeFromSave();Check(GameplayLevelCatalog.SelectedId==1,"Missing or unverified saved selection safely falls back");p.SetCurrentLevel(1);});
  Tap("NavMap");Add(()=>{Check(SceneManager.GetActiveScene().name=="LevelMap","Home Map navigation");Capture("MAP");BeginSample();});for(int i=0;i<5;i++)Add(()=>{});Add(()=>EndSample("LevelMap"));Tap("MapHome");
  Tap("EventsButton");Add(()=>{Check(UnityEngine.Object.FindFirstObjectByType<RewardHubPanel>().IsOpen,"Events actual panel");Capture("EVENTS");BeginSample();});for(int i=0;i<5;i++)Add(()=>{});Add(()=>EndSample("Events"));Tap("RewardHubClose");
  Add(()=>{expectedTransitions=transitions+1;Check(Mewgic.SceneNavigation.LoadOnce("Gameplay"),"First navigation accepted");Check(!Mewgic.SceneNavigation.LoadOnce("Gameplay"),"Same-frame repeated scene navigation rejected");});
  Add(()=>{Check(transitions==expectedTransitions,"Only one deferred sceneLoaded notification");Check(SceneManager.GetActiveScene().name=="Gameplay","Gameplay loaded");Capture("GAMEPLAY");BeginSample();});for(int i=0;i<5;i++)Add(()=>{});Add(()=>EndSample("Gameplay"));
  Add(()=>{var app=UnityEngine.Object.FindFirstObjectByType<PrototypeApp>();app.SendMessage("OnApplicationPause",true);Check(app.IsPaused,"Application suspension pauses puzzle");app.ResumeGame();Check(!app.IsPaused,"Resume after suspension");});Tap("Home");
  Add(()=>{Check(SceneManager.GetActiveScene().name=="Home","Gameplay Home return");Check(GameplayProgress.Current.Completed(1)&&GameplayProgress.Current.Presentation.soundEnabled,"Progress and settings retained across scenes");});
  SessionState.SetBool("BetaPlayTest",true);EditorSceneManager.OpenScene("Assets/Scenes/Boot.unity");EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();Application.runInBackground=true;EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+2;
 }
 static void SettingsLayout(int width,int height,bool inset)
 {
  var r=(RectTransform)GameObject.Find("SoundToggle").transform;var safe=(RectTransform)r.parent.parent;var canvas=safe.GetComponentInParent<Canvas>();var cam=Camera.main;var mode=canvas.renderMode;var previous=canvas.worldCamera;float distance=canvas.planeDistance;var min=safe.anchorMin;var max=safe.anchorMax;var target=cam.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(width,height,24);Texture2D tex=null;
  try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;cam.targetTexture=rt;if(inset){safe.anchorMin=new Vector2(.04f,.05f);safe.anchorMax=new Vector2(.96f,.96f);}Canvas.ForceUpdateCanvases();Check(r.rect.width*canvas.scaleFactor>=43.9f&&r.rect.height*canvas.scaleFactor>=43.9f,"Settings touch target >=44 pixels "+width+"x"+height);var c=new Vector3[4];r.GetWorldCorners(c);foreach(var v in c)Check(safe.rect.Contains(safe.InverseTransformPoint(v)),"Settings sound target inside safe area "+width+"x"+height);cam.Render();RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes(output+"settings-"+width+"x"+height+".png",tex.EncodeToPNG());}
  finally{cam.targetTexture=target;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=previous;canvas.planeDistance=distance;safe.anchorMin=min;safe.anchorMax=max;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();}
 }
 static void Finish(string error){sampling=false;gc.Dispose();SceneManager.sceneLoaded-=SceneLoaded;SessionState.SetBool("BetaPlayTest",false);if(PlayerPrefs.HasKey(GameplayProgress.StorageKey)!=had||PlayerPrefs.GetString(GameplayProgress.StorageKey,"")!=original)error=(error??"")+" Player save changed";else checks.Add("Actual player save untouched");File.WriteAllText("docs/PART08_PLAY_TESTS.json",JsonUtility.ToJson(new BetaValidation.Result{success=error==null,error=error,checks=checks.ToArray()},true));File.WriteAllText("docs/PART08_EDITOR_PERFORMANCE.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{note="Editor Play Mode, unprofiled build; GC includes Editor/test/MCP activity, not Android device performance",screens=performance},Newtonsoft.Json.Formatting.Indented));EditorApplication.isPlaying=false;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();AudioListener.volume=volume;}
 static void Tick(){if(!SessionState.GetBool("BetaPlayTest",false)||!EditorApplication.isPlaying)return;if(!ready){if(SceneManager.GetActiveScene().name!="Home"||GameObject.Find("Play")==null){if(EditorApplication.timeSinceStartup>deadline)Finish("Home ready timeout");return;}ready=true;}if(sampling&&gc.Valid)samples.Add(gc.LastValue);if(EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+.75;if(actions.Count==0){Finish(null);return;}actions.Dequeue()();}catch(Exception e){Finish(e.ToString());}}
}
